@@
-   IF jsonb_typeof(d->'entryId') <> 'string' THEN RETURN false; END IF;
+   IF jsonb_typeof(d->'entryId') <> 'string' OR NOT clearledger.uuid_ok(d->>'entryId') THEN RETURN false; END IF;
@@
- AND btrim(debit_party) <> btrim(credit_party) AND clearledger.bounded(current_stage,2,64)
